/**
 * A phone number, reported as one E.164 string (`design/components/phone-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/phone-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  afterRender,
  agentMember,
  claimSlot,
  commitPhone,
  composingKey,
  createCell,
  createDerived,
  devWarning,
  elementRef,
  isPhoneValue,
  phoneCountries,
  phoneCountryOptions,
  phoneDefaultCountry,
  phoneDraft,
  readPhone,
  scope,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/phone-input.module.css'
import Combobox from './Combobox'
import Input from './Input'

export interface PhoneInputMessages {
  country?: string
  showCountries?: string
  countriesShown?: (count: number) => string
  noCountry?: string
}

export interface PhoneInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * The regions offered, in this order. Every region, sorted by name, when omitted.
   */
  countries?: string[]
  /**
   * ISO 3166-1 alpha-2. The country shown before the reader chooses one, while the value names
   * none. Defaults to the first of `countries`, else the United States.
   */
  defaultCountry?: string
  defaultValue?: string
  disabled?: boolean
  /**
   * On the number's `<input>`, so a link to the field reaches a control that takes focus.
   */
  id?: string
  invalid?: boolean
  /**
   * The language of the country names and of their order.
   */
  locale?: string
  /**
   * Every word the member writes itself. See `PhoneInputMessages`.
   */
  messages?: PhoneInputMessages
  /**
   * Serializes the committed E.164 value in one hidden input.
   */
  name?: string
  /**
   * Reports commits, never drafts, as NumberInput does: the reader leaves the number or presses
   * Enter in it, chooses a country, or pastes a number written with its calling code. It fires
   * only for a value that differs from the one the field holds.
   */
  onChange?: (value: string) => void
  /**
   * The number stays focusable and selectable, and the country is shown as read-only text.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * An E.164 string (`+442079460958`), or the empty string while the national number has no
   * digits. A value that is not E.164 is drawn as well as it can be, with a development warning.
   */
  value?: string
}

/** A phone number, reported as one E.164 string. */
export default function PhoneInput(given: PhoneInputProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', disabled: false, readOnly: false, invalid: false } as Defaults<
      PhoneInputProps,
      'size' | 'disabled' | 'readOnly' | 'invalid'
    >,
    claimSlot(given, 'group'),
  )
  return scope(() => {
    const uid = createUniqueId()
    const root = elementRef<HTMLElement>()
    const browserLanguage = createCell(undefined as string | undefined)
    const kept = createCell(props.defaultValue ?? '')
    const chosen = createCell(
      readPhone(props.value ?? props.defaultValue ?? '', {
        country: phoneDefaultCountry(props.defaultCountry, props.countries),
        countries: props.countries,
      }).country,
    )
    const draft = createCell(null as string | null)
    const typed = createCell(null as { text: string; under: string } | null)
    const language = createDerived(() => props.locale ?? browserLanguage.value ?? 'en-US')
    const say = createDerived(() => ({
      country: 'Country calling code',
      showCountries: 'Show countries',
      countriesShown: (count: number) => `${count} countries`,
      noCountry: 'No matching country',
      ...props.messages,
    }))
    const current = createDerived(() => props.value ?? kept.value)
    const drawn = createDerived(() =>
      readPhone(current.value, { country: chosen.value, countries: props.countries }),
    )
    const country = createDerived(() => drawn.value.country)
    const national = createDerived(() => draft.value ?? drawn.value.national)
    const options = createDerived(() =>
      phoneCountryOptions({
        locale: language.value,
        countries: props.countries,
        include: country.value,
      }),
    )
    const countryLabel = createDerived(
      () => options.value.find((option) => option.value === country.value)?.label ?? '',
    )
    const countryText = createDerived(() =>
      typed.value !== null && typed.value.under === country.value
        ? typed.value.text
        : countryLabel.value,
    )
    const countryId = createDerived(() => `${uid}-country`)
    const countryLabelledby = createDerived(() =>
      props['aria-labelledby'] === undefined
        ? undefined
        : `${countryId.value} ${props['aria-labelledby']}`,
    )
    const commit = createDerived(() => (next: string, text: string): void => {
      const result = commitPhone(next, text, { countries: props.countries })
      chosen.value = result.country
      draft.value = result.value === '' && result.national !== '' ? result.national : null
      if (result.value !== current.value) {
        kept.value = result.value
        props.onChange?.(result.value)
      }
    })
    const commitDraft = createDerived(() => (): void => {
      if (draft.value !== null) commit.value(country.value, draft.value)
    })
    const fitNumber = createDerived(() => (event: Event): void => {
      const field = event.target
      if (field instanceof HTMLInputElement && field.type === 'tel')
        afterRender(() => {
          if (field.value !== national.value) field.value = national.value
        })
    })
    const pasteInto = createDerived(() => (event: ClipboardEvent): void => {
      const field = event.target
      if (props.readOnly || !(field instanceof HTMLInputElement) || field.type !== 'tel') return
      const pasted = event.clipboardData?.getData('text/plain') ?? ''
      event.preventDefault()
      if (pasted.trimStart().startsWith('+')) {
        const result = commitPhone(country.value, pasted, { countries: props.countries })
        if (result.value === '') draft.value = result.national
        else commit.value(country.value, pasted)
        return
      }
      const start = field.selectionStart ?? national.value.length
      const end = field.selectionEnd ?? national.value.length
      draft.value = phoneDraft(
        `${national.value.slice(0, start)}${pasted}${national.value.slice(end)}`,
        country.value,
      )
    })
    const effect1 = () => {
      browserLanguage.value = globalThis.navigator?.language
    }
    onMount(effect1)
    const effect2 = () => {
      devWarning(
        current.value !== '' && !isPhoneValue(current.value),
        `PhoneInput: the value "${current.value}" is not an E.164 string. Pass +, the calling code and the national number, or the empty string.`,
      )
    }
    watchEffect(
      createMemo(() => current.value),
      effect2,
      true,
    )
    const effect3 = () => {
      devWarning(
        props.countries !== undefined &&
          phoneCountries(props.countries).length !== props.countries.length,
        'PhoneInput: `countries` repeats a region or names one with no calling code. Each is listed once, and those are dropped.',
      )
    }
    watchEffect(
      createMemo(() => props.countries),
      effect3,
      true,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = agentMember({
        member: 'PhoneInput',
        element: () => root.value,
        state: () => ({
          value: current.value,
          country: country.value,
          disabled: props.disabled,
          invalid: props.invalid,
          readonly: props.readOnly,
        }),
        actions: {
          set: {
            argument: 'text',
            run: (value) =>
              (() => {
                if (props.readOnly) throw new Error('The field is read-only.')
                if (
                  commitPhone(country.value, value, { countries: props.countries }).value === ''
                ) {
                  throw new Error(`"${value}" is not a phone number the field can read.`)
                }
                commit.value(country.value, value)
              })(),
          },
          clear: () =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              commit.value(country.value, '')
            })(),
        },
        withholds: () => root.value,
      })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <div
        class={styles.root}
        role="group"
        aria-label={props['aria-label']}
        aria-labelledby={props['aria-labelledby']}
        aria-describedby={props['aria-describedby']}
        data-size={props.size}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-readonly={props.readOnly ? '' : undefined}
        data-member="phone-input"
        ref={root.attach}
      >
        {/* country */}
        <span class={styles.country}>
          {props.readOnly ? (
            <Input
              value={countryLabel.value}
              readOnly={true}
              size={props.size}
              invalid={props.invalid}
              disabled={props.disabled}
              id={countryId.value}
              aria-label={say.value.country}
              aria-labelledby={countryLabelledby.value}
              aria-describedby={props['aria-describedby']}
            />
          ) : (
            <Combobox
              options={options.value}
              value={country.value}
              inputValue={countryText.value}
              size={props.size}
              invalid={props.invalid}
              disabled={props.disabled}
              id={countryId.value}
              messages={{
                showOptions: say.value.showCountries,
                options: say.value.countriesShown,
                list: say.value.country,
              }}
              emptyMessage={say.value.noCountry}
              aria-label={say.value.country}
              aria-labelledby={countryLabelledby.value}
              aria-describedby={props['aria-describedby']}
              onChange={($event) => $event !== null && commit.value($event, national.value)}
              onInputChange={($event) => (typed.value = { text: $event, under: country.value })}
            />
          )}
        </span>
        {/* number */}
        <span
          class={styles.number}
          onkeydown={($event: KeyboardEvent) =>
            $event.key === 'Enter' && !composingKey($event) && commitDraft.value()
          }
          onpaste={($event: ClipboardEvent) => pasteInto.value($event)}
          oninput={($event: InputEvent) => fitNumber.value($event)}
        >
          <Input
            type="tel"
            value={national.value}
            size={props.size}
            invalid={props.invalid}
            disabled={props.disabled}
            readOnly={props.readOnly}
            id={props.id}
            autoComplete="tel-national"
            aria-label={props['aria-label']}
            aria-labelledby={props['aria-labelledby']}
            aria-describedby={props['aria-describedby']}
            aria-required={props['aria-required']}
            onChange={($event) => (draft.value = phoneDraft($event, country.value))}
            onBlur={() => commitDraft.value()}
          />
        </span>
        {props.name !== undefined ? (
          <input
            type="hidden"
            name={props.name}
            value={current.value}
            disabled={props.disabled || undefined}
          />
        ) : null}
      </div>
    )
  })
}

PhoneInput.controlKind = 'group'
